            {{ Math.round(getProgressPercentage()) }}%
          </div>
          <div class="stat-label">Complete</div>
        </div>

        <div class="stat-card">
          <div class="stat-number">{{ getETAText() }}</div>
          <div class="stat-label">ETA</div>
        </div>

        <div class="stat-card">
          <div class="stat-number">{{ processStats.completedSteps }}</div>
          <div class="stat-label">Steps Done</div>
        </div>

        <div class="stat-card">
          <div class="stat-number">{{ getRemainingSteps() }}</div>
          <div class="stat-label">Remaining</div>
        </div>
      </div>

      <!-- Visual Progress Bar -->
      <div class="main-progress-bar">
        <div class="progress-track-public">
          <div
            class="progress-fill-public"
            :style="getMainProgressStyle()"
          ></div>
        </div>
        <div class="progress-labels">
          <span class="progress-start">Started</span>
          <span class="progress-end">Complete</span>
        </div>
      </div>
    </div>

    <!-- Processing Steps Visualization -->
    <div class="processing-steps">
      <h3 class="steps-title">Processing Pipeline</h3>

      <div class="steps-grid">
        <div
          v-for="(step, index) in processSteps"
          :key="step.id"
          :class="['step-card-public', getPublicStepClass(step)]"
        >
          <!-- Step Number -->
          <div class="step-number">{{ index + 1 }}</div>

          <!-- Step Status Icon -->
          <div class="step-status">
            <q-icon
              :name="getStepStatusIcon(step)"
              :class="getStepIconClass(step)"
            />
          </div>

          <!-- Step Info -->
          <div class="step-info">
            <div class="step-name">{{ formatStepName(step.name) }}</div>
            <div
              class="step-timing"
              v-if="step.success || step.action === 'running'"
            >
              {{ getStepTimingText(step) }}
            </div>
            <div class="step-status-text" :class="getStepStatusTextClass(step)">
              {{ getStepStatusText(step) }}
            </div>
          </div>

          <!-- SLA Status for Public View -->
          <div
            class="step-sla"
            v-if="step.success || step.action === 'running'"
          >
            <q-icon
              :name="getStepSLAIcon(step)"
              :class="getStepSLAClass(step)"
            />
          </div>
        </div>
      </div>
    </div>

    <!-- Footer Section -->
    <div class="public-footer">
      <div class="footer-content">
        <div class="last-update">Last updated: {{ getLastUpdateTime() }}</div>
        <div class="refresh-notice">
          This page auto-refreshes every 30 seconds
        </div>
        <div class="powered-by">
          Powered by <strong>DocBits</strong> - Intelligent Document Processing
        </div>
      </div>
    </div>
