<script>
import { documentFlowDataService } from 'src/services';

export default {
  name: 'PublicDocumentStatus',
  props: {
    documentId: {
      type: String,
      required: true,
    },
    shareToken: {
      type: String,
      required: false,
    },
  },

  data() {
    return {
      documentInfo: {
        name: '',
        type: '',
        uploadedAt: null,
        uploadedBy: '',
      },
      processSteps: [],
      lastUpdate: new Date(),
      refreshInterval: null,
      isLoading: true,
      errorMessage: null,
    };
  },

  computed: {
    processStats() {
      const stats = {
        totalSteps: this.processSteps.length,
        completedSteps: 0,
        runningSteps: 0,
        waitingSteps: 0,
        overallStatus: 'WAITING',
      };

      this.processSteps.forEach((step) => {
        if (step.success === true) {
          stats.completedSteps++;
        } else if (step.action === 'running' || step.action === 'starting') {
          stats.runningSteps++;
        } else {
          stats.waitingSteps++;
        }
      });

      // Determine overall status
      if (stats.runningSteps > 0) {
        stats.overallStatus = 'PROCESSING';
      } else if (stats.completedSteps > 0 && stats.waitingSteps === 0) {
        stats.overallStatus = 'COMPLETED';
      } else {
        stats.overallStatus = 'WAITING';
      }

      return stats;
    },
  },

  async mounted() {
    await this.loadDocumentStatus();
    this.startAutoRefresh();
  },

  beforeUnmount() {
    this.stopAutoRefresh();
  },

  methods: {
    async loadDocumentStatus() {
      try {
        this.isLoading = true;
        this.errorMessage = null;

        // Load document flow data using existing API
        const response = await documentFlowDataService.getData(this.documentId);

        if (response.success) {
          this.processSteps = response.flow_data || [];
          this.documentInfo = response.document_info || {};
          this.lastUpdate = new Date();
        } else {
          this.errorMessage =
            'Unable to load document status. Please check the link.';
        }
      } catch (error) {
        this.errorMessage = 'Connection error. Please try again later.';
        console.error('Public status page error:', error);
      } finally {
        this.isLoading = false;
      }
    },

    startAutoRefresh() {
      // Refresh every 30 seconds for real-time updates
      this.refreshInterval = setInterval(async () => {
        await this.loadDocumentStatus();
      }, 30000);
    },

    stopAutoRefresh() {
      if (this.refreshInterval) {
        clearInterval(this.refreshInterval);
        this.refreshInterval = null;
      }
    },

    // Progress calculation methods
    getProgressPercentage() {
      if (this.processStats.totalSteps === 0) return 0;
      return (
        (this.processStats.completedSteps / this.processStats.totalSteps) * 100
      );
    },

    getRemainingSteps() {
      return this.processStats.runningSteps + this.processStats.waitingSteps;
    },

    getETAText() {
      const remaining = this.getRemainingSteps();
      if (remaining === 0) return 'Complete';

      // Estimate 45 seconds per remaining step (conservative for public view)
      const estimatedMinutes = (remaining * 45) / 60;

      if (estimatedMinutes < 1) return '< 1 min';
      if (estimatedMinutes < 60) return `${Math.round(estimatedMinutes)} min`;

      const hours = Math.floor(estimatedMinutes / 60);
      const minutes = Math.round(estimatedMinutes % 60);
      return `${hours}h ${minutes}m`;
    },

    // Overall status methods
    getOverallStatusClass() {
      return `status-${this.processStats.overallStatus.toLowerCase()}`;
    },

    getOverallStatusIcon() {
      switch (this.processStats.overallStatus) {
        case 'COMPLETED':
          return 'check_circle';
        case 'PROCESSING':
          return 'autorenew';
        case 'WAITING':
          return 'schedule';
        default:
          return 'schedule';
      }
    },

    getOverallStatusText() {
      switch (this.processStats.overallStatus) {
        case 'COMPLETED':
          return 'Processing Complete';
        case 'PROCESSING':
          return 'Currently Processing';
        case 'WAITING':
          return 'In Queue';
        default:
          return 'Processing Status';
      }
    },

    getStatusSubtitle() {
      if (this.processStats.overallStatus === 'COMPLETED') {
        return 'Your document is ready for download';
      } else if (this.processStats.overallStatus === 'PROCESSING') {
        return `Step ${this.processStats.completedSteps + 1} of ${this.processStats.totalSteps}`;
      } else {
        return 'Your document is queued for processing';
      }
    },

    // Progress bar styling
    getMainProgressStyle() {
      const percentage = this.getProgressPercentage();
      let color = '#17a2b8'; // Blue for early stages

      if (percentage >= 80)
        color = '#28a745'; // Green for near completion
      else if (percentage >= 50) color = '#fd7e14'; // Orange for mid-progress

      return {
        width: `${percentage}%`,
        background: `linear-gradient(90deg, ${color}, ${color}dd)`,
        transition: 'all 0.8s ease',
      };
    },

    // Step formatting methods
    formatStepName(stepName) {
      const stepNames = {
        import: 'Import',
        ocr: 'Text Recognition',
        classification: 'Classification',
        field_extraction: 'Data Extraction',
        table_extraction: 'Table Processing',
        barcode_extraction: 'Barcode Reading',
        validation: 'Validation',
        approval: 'Review & Approval',
        export: 'Final Processing',
      };

      return (
        stepNames[stepName] ||
        stepName.replace(/_/g, ' ').replace(/\b\w/g, (l) => l.toUpperCase())
      );
    },

    getPublicStepClass(step) {
      if (step.success === true) return 'step-completed';
      if (step.action === 'running' || step.action === 'starting')
        return 'step-processing';
      return 'step-waiting';
    },

    getStepStatusIcon(step) {
      if (step.success === true) return 'check_circle';
      if (step.action === 'running') return 'autorenew';
      if (step.action === 'starting') return 'play_arrow';
      return 'schedule';
    },

    getStepIconClass(step) {
      return {
        'step-icon-completed': step.success === true,
        'step-icon-processing':
          step.action === 'running' || step.action === 'starting',
        'step-icon-waiting':
          step.success !== true &&
          step.action !== 'running' &&
          step.action !== 'starting',
      };
    },

    getStepTimingText(step) {
      if (step.time && step.time !== '-') {
        return `${step.time}`;
      }
      return '-';
    },

    getStepStatusText(step) {
      if (step.success === true) return 'Complete';
      if (step.action === 'running') return 'Processing...';
      if (step.action === 'starting') return 'Starting...';
      return 'Waiting';
    },

    getStepStatusTextClass(step) {
      return {
        'status-text-completed': step.success === true,
        'status-text-processing':
          step.action === 'running' || step.action === 'starting',
        'status-text-waiting':
          step.success !== true &&
          step.action !== 'running' &&
          step.action !== 'starting',
      };
    },

    // SLA indicators for public view
    getStepSLAIcon(step) {
      // Simplified SLA logic for public display
      const timing = parseFloat((step.time || '0').replace('s', ''));
      const stepSLAs = {
        ocr: 30,
        classification: 15,
        field_extraction: 45,
        table_extraction: 60,
        default: 30,
      };

      const slaTarget = stepSLAs[step.name] || stepSLAs.default;

      if (timing <= slaTarget) return 'check_circle';
      if (timing <= slaTarget * 1.5) return 'schedule';
      return 'error';
    },

    getStepSLAClass(step) {
      const timing = parseFloat((step.time || '0').replace('s', ''));
      const stepSLAs = {
        ocr: 30,
        classification: 15,
        field_extraction: 45,
        table_extraction: 60,
        default: 30,
      };

      const slaTarget = stepSLAs[step.name] || stepSLAs.default;

      return {
        'sla-public-good': timing <= slaTarget,
        'sla-public-warning': timing > slaTarget && timing <= slaTarget * 1.5,
        'sla-public-error': timing > slaTarget * 1.5,
      };
    },

    // Utility methods
    getLastUpdateTime() {
      return this.lastUpdate.toLocaleTimeString();
    },
  },
};
</script>

